"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5093],{85093:n=>{n.exports=JSON.parse('{"id":"base-12","slug":"base-12","trackId":"base","order":13,"title":"贩卖预测的人","subtitle":"清晰易懂的资金保护规则","estimatedMinutes":14,"access":"free","quizCount":3,"blueprintCount":0,"trainerIds":["HUB-CALC-05","HUB-CALC-06"],"markdown":"第 12 课 \xb7 9 分钟\\n\\n## 贩卖预测的人\\n\\n向你出售预测的人如何赚钱\\n\\n交易所课程说明了为什么交易是职业，而不是轻松赚钱的方法。上一课整理了让新手亏损的常见错误。但很多人始终没有问过一个问题：既然持续交易获利如此困难，出售预测、信号和课程的人，为什么拥有豪车、旅行，以及盈利 500% 的截图？\\n\\n答案令人不快，却很简单：\\n\\n他们中的大多数不是从市场赚钱，而是从你身上赚钱。\\n\\n这不意味着每个讨论加密货币的人都是骗子。但评估任何建议前，先要理解建议者的收入机制。\\n\\n### 关键问题：谁在给博主付钱？\\n\\n每种媒体都有商业模式。电视台靠广告，报纸靠订阅，银行分析师领取银行工资，加密网红也一样。所以听预测之前，值得先问：\\n\\n这个人如何赚钱？他的收入是否取决于我能否赚钱？\\n\\n答案经常是：他的收入取决于你有多活跃，而不是你能否盈利。下面分析主要来源。\\n\\n### 1. 交易所推荐链接\\n\\n这是最常见、也最不显眼的收入来源。几乎所有大型加密交易所，都会向合作伙伴支付所推荐用户交易手续费的一定比例。例如，Bybit 合作计划承诺最高分配被推荐客户交易手续费的 50%，其他大型交易所也有类似条款。流程如下：\\n- 博主提供“粉丝专享奖励”链接；\\n- 你通过该链接注册；\\n- 每次开仓和平仓，交易所收取手续费；\\n- 博主长期获得其中一部分。\\n\\n关键细节：博主分得的是手续费，而不是你的利润。你盈利，他赚钱；你亏损，他仍然赚钱。\\n\\n点击放大\\n\\n#### 用简单例子计算\\n\\n假设你有 $1 000，使用 20 倍杠杆交易期货，每笔头寸为 $20 000。大型交易所期货手续费假设为开仓约 0.05%，平仓同样 0.05%，则：\\n\\n$20 000 \xd7 0.05% \xd7 2 = 每笔交易 $20。\\n\\n一笔交易就消耗账户资金的 2%，即使价格根本没变。再假设你按频道建议，每天交易 5 次。\\n\\n$20 \xd7 5 = 每天 $100，即账户资金的 10%。\\n\\n如果交易本身的盈亏为零，10 个交易日后，手续费就耗尽全部资金。博主若分成 40%，每天从你身上得到 $40。如果有 100 位这样的粉丝，就是每天 $4 000，而他自己一笔交易都不用做。\\n\\n因此，博主希望你交易更频繁、杠杆更高、金额更大。这恰恰是你最好避免的行为。\\n\\n这也是为什么这些频道总在催促“别错过入场”“加杠杆”“继续加仓”。\\n\\n你有 $1 000，并使用博主链接，谁会赚钱？20 倍杠杆，每天 5 笔交易。\\n\\n$20\\n\\n每笔交易\\n\\n$100\\n\\n每天\\n\\n$40\\n\\n博主每天所得。即使交易盈亏为零，手续费也会在 10 天内耗尽资金。40% 分成的博主，仅从你一人每天获得 $40；100 位粉丝就是 $4 000。\\n\\n### 2. 付费信号和 VIP 频道\\n\\n第二种常见模式：免费频道配合提供信号的付费 VIP 群。先展示几笔成功交易，再推销每月 $50、$100 或 $300 的订阅。问自己一个简单问题：\\n\\n如果一个人能稳定每月赚 10%，为什么还要卖 $100 的信号？\\n\\n算一算：$10 000 以每月 10% 复利增长，一年后约为 $31 000，5 年后约为 $3 000 000。拥有这种能力的人，需要的只是自己的资金和时间，而不是粉丝。\\n\\n因此，卖信号几乎总意味着以下两者之一：\\n- 策略并没有广告所说的那样稳定；\\n- 主要收入来自订阅和推荐手续费，而不是交易。\\n\\n信号还常搭配推荐链接，博主收两次钱：一次是订阅费，另一次是你按信号交易产生的手续费分成。\\n\\n### 3. 课程、导师辅导与“生活方式”\\n\\n第三种来源是交易培训。教学本身没有问题，本课程也是教育。问题是有时出售的并非知识，而是梦想。\\n\\n镜头里的豪车、酒店、海景、盈利截图，都不能证明对方靠市场赚钱。汽车可以租一天，截图可以来自模拟账户，住酒店的钱也可能来自卖课。\\n\\n卖课者的生活方式，只能证明一件事：课程卖得不错。\\n\\n### 4. 代币付费广告\\n\\n第四种来源是项目付钱让博主提及代币。广告经常不标注，伪装成个人意见：“发现一个有趣项目”“这是我本轮周期最看好的项目”。\\n\\n最知名的例子是 2022 年，美国证券监管机构 SEC 对金\xb7卡戴珊处罚。她收取 $250 000，在 Instagram 发帖宣传 EMAX，却未告知粉丝这是广告，最终支付 $126 万的罚款及相关款项。\\n\\n但明星只是冰山一角。\\n\\n2025 年 9 月，独立区块链调查者 ZachXBT 公布某代币广告活动的泄露表格。据其资料，160 多名加密博主同意按每帖 $50 至 $60 000 收费，标注广告的不足 5 人。\\n\\n也就是说，你喜欢的博主所谓“独立观点”，完全可能是付费帖子。\\n\\n### 5. 拉高出货：直接从粉丝身上获利\\n\\n这是最直接的收割方式。\\n- 博主或关联人员提前买入不知名代币；\\n- 博主发热情洋溢的帖子：“下一个百倍币”；\\n- 粉丝买入，价格上涨；\\n- 早期买家把代币高价卖给粉丝；\\n- 价格下跌，粉丝承担损失。\\n\\n博主甚至不用谎称自己买过。他确实买了，只是比你更早、更便宜。2025 年，阿根廷总统哈维尔\xb7米莱发布关于 LIBRA 迷因币的帖子。价格飙升，几小时后又因大型早期持有人抛售而暴跌，米莱因此受到司法调查。\\n\\n加密市场分析公司 Solidus Labs 统计，热门平台 Pump.fun 上发行的迷因币中，98.6% 出现拉高出货迹象。\\n\\n有人催你立刻买不知名代币时，请记住：你可能不是投资者，而是别人退出时需要的流动性。\\n\\n### 6. 跟单与“代客理财”\\n\\n另一种说法是：“复制我的交易”或“把钱交给我管理”。很多交易所有跟单功能，连接某位交易者后，其交易会自动复制到你的账户。交易者获得粉丝利润的一定比例。注意这种不对称：盈利时，他拿分成。\\n\\n亏损时，却全部由你承担。交易者几乎不承担风险，又能分享收益，因此有动机比你自己愿意的程度冒更大风险。网上无牌照人士提供的“代客理财”，最好的情况也缺乏保障，最坏可能就是金融骗局。\\n\\n### 7. 注意力也是商品\\n\\n还有更隐蔽的机制。社交媒体算法推广能引发情绪的内容。自信声称“比特币会涨到 $200 000”，比诚实地说“没人知道价格往哪里走”更容易获得浏览量。半年后，几乎没人核对预测。错误被遗忘，正确的却成了传奇，以及永久证明专业性的素材。\\n\\n伯克利和洛桑研究人员的一项研究清楚说明这一点。他们分析 StockTwits 社交平台上的金融网红建议，发现：\\n- 只有 28% 的建议平均能带来盈利；\\n- 16% 未体现出任何能力；\\n- 56% 的建议平均会让跟随者亏损。\\n\\n最糟的是，建议导致亏损的人，粉丝反而比真正有能力的人更多。知名度与专业水平是两回事，有时甚至相反。\\n\\n### 为什么他们的截图总是漂亮\\n\\n即使毫无能力，统计表现也可能看起来完美。下面是几种方法。\\n\\n#### 幸存者偏差\\n\\n设想 1 024 人随机预测价格上涨或下跌。第一轮约一半猜对，即 512 人；第二轮剩 256 人；第三轮 128 人；第四轮 64 人；第五轮，仍有 32 人连续猜对 5 次。\\n\\n他们并不具备任何特殊能力，这只是数学。但旁观者会觉得这 32 人是天才。信息流里，你看到的恰恰就是他们。其余 992 人悄悄删除了频道。\\n\\n1 024 人随机猜测价格。\\n\\n1024\\n\\n尚无人开始预测\\n\\n#### 两个频道\\n\\n博主同时经营两个频道，一个喊买，一个喊卖。之后关闭亏损的频道，把盈利频道展示为预测准确的证据。\\n\\n#### 删除信号\\n\\n错误预测被删除或修改，只留下成功案例。\\n\\n#### 没有背景的截图\\n\\n+500% 的盈利很惊人，但截图不会告诉你：头寸只有 $20、杠杆 100 倍，另一个账户已经被强平，或这其实是模拟账户。\\n\\n盈利截图不能证明任何事。只有在结果揭晓前发布的全部交易历史，才能作为证据。\\n\\n### 国家如何应对\\n\\n许多国家的监管机构已经关注金融网红。\\n\\n俄罗斯自 2024 年 8 月起禁止加密货币广告。自 2026 年 9 月 1 日起，只有合法中介可以宣传自身服务，并且必须提供风险信息。因此，即使未标注，博主提供的外国交易所“奖励链接”也应视为广告。\\n\\n2026 年 2 月，俄罗斯央行发布金融网红监管报告。报告引用 NAFI 研究：37% 的投资者从主题 Telegram 频道获取知识，29% 参考博主建议。\\n\\n央行提出建立金融网红名册、资格要求，并强制披露利益冲突。讨论后，监管机构计划先推行自愿“白名单”和伦理规范。但规则仍在形成，用户仍需自行核查来源。\\n\\n### 检查清单：如何核查向你卖预测的人\\n\\n跟随他人建议前，回答七个问题。1. 他如何赚钱？推荐链接、订阅、课程、广告，还是管理他人资金？2. 我亏损时，他也赚钱吗？若是，双方利益不同。3. 是否有完整统计？是否包括全部亏损信号，并且发布时间早于事件？\\n\\n4. 他是否讨论风险和亏损，还是只谈利润？5. 他是否催促？“最后机会”“立即入场”“只剩 10 分钟”。6. 是否标注广告？是否披露自己持有正在介绍的代币？\\n\\n7. 如果策略有效，为什么还要出售它？\\n\\n如果大多数答案让人担忧，最好跳过。\\n\\n### 这些问题也适用于我们\\n\\n坦诚地说，我们也是媒体，也会赚钱，收入来自课程、订阅和广告。因此，也请向我们提出这些问题。这很正常。好的作者不会因为“你如何赚钱？”而生气，只会作出回答。\\n\\n### 最重要的几点\\n\\n多数出售预测、信号和交易课程的人，收入来自受众，而不是市场。你交易越频繁、冒险越多、购买越多推荐产品，他们赚得越多，即使你在亏钱。知名度不等于专业水平，截图不等于完整统计，自信语气不等于知识。\\n\\n在问“价格往哪里走”之前，先问：“如果我听从这个建议，谁会赚钱？”\\n\\n本课程到此结束。现在你有了基础：理解加密货币如何运作，如何存储、转移和购买，以及风险从哪里开始。最重要的是，知道把钱交给别人之前，应该问哪些问题。\\n\\n### 自测 1 / 3\\n\\n博主提供交易所推荐链接，并建议每天进行杠杆期货交易。他如何赚钱？\\n\\n\\n### 本课内嵌术语：\\n- **比特币**——第一种加密货币，旨在成为无需中介的货币。总量严格限制为 2 100 万枚，已存在 15 年以上，经历多次崩盘后均曾恢复，被称为“数字黄金”。\\n- **区块链**——所有人都能查看的交易记录表：可以新增记录，但不能修改旧记录。它同时保存在数百万台计算机上，因此无法从物理层面伪造历史。\\n- **清算**——抵押品贬值后被强制出售。在加密领域，代码会直接按条件执行，不会有人打电话提醒你。\\n- **流动性**——能迅速把资产换成资金而不受损失的能力。应急资金应具有流动性，确保随时可用。\\n- **迷因币**——缺乏技术和核心理念、依赖炒作生存的加密货币（DOGE、SHIB）。偶尔上涨数百倍，但更常见的结果是归零。它更像彩票，而不是投资。\\n- **复利**——利息也会继续产生利息。它是长期投资者的重要伙伴：现在投入的 10 000 ₽，20 年后可能比 10 年后才投入的 100 000 ₽ 更有价值。\\n- **SEC（美国证券监管机构）**——源于 1929 年危机后设立的美国监管机构。2024 年批准现货 Bitcoin ETF，为机构进入加密资产市场打开通道。\\n- **期货**——约定未来按今天商定的价格买入或卖出某项标的的合约。期货价格反映市场对油价、美国联邦储备利率决定等事项的预期。它是预期，不是预测，市场经常出错。\\n- **代币**——存在于某一网络中的数字资产，例如 USDT 或 USDC。同一种代币可以出现在不同网络中，而它们属于不同版本。\\n- **杠杆**——借入资金使头寸规模超过自有资金：用 $1 000 和 10 倍杠杆，可建立 $10 000 的头寸。价格变动对资金的影响会放大 10 倍，盈亏两个方向都如此。\\n- **跟单交易**——你的账户自动复制另一位交易者的交易。盈利时对方会分成，亏损则全部由你承担。\\n- **拉高出货**——先买入不知名代币，再通过发帖炒作推高价格，最后在高位卖给粉丝。买家则承受亏损。\\n\\n### 课后测试（“自测”）：\\n**问题 1： 博主提供交易所推荐链接，并建议每天进行杠杆期货交易。他如何赚钱？**\\n- ⚪ 选项 1： 只从你的利润中提成，因此与你利益一致\\n- ✅ **[正确答案]** 选项 2： 获得交易手续费分成，因此你任何交易都会让他赚钱，即使你亏损\\n- ⚪ 选项 3： 没有任何收入，链接只是给粉丝福利\\n\\n**问题 2： 频道展示连续 5 次正确预测，这能说明什么？**\\n- ⚪ 选项 1： 作者肯定是专业人士，可以把钱交给他\\n- ✅ **[正确答案]** 选项 2： 单凭这些几乎无法判断；重要的是事件发生前发布的全部预测历史\\n- ⚪ 选项 3： 第 6 次预测也一定准确\\n\\n**问题 3： 知名博主催促立即购买某个陌生新代币，以免“起飞”。怎样做最安全？**\\n- ⚪ 选项 1： 赶在上涨前全仓买入\\n- ⚪ 选项 2： 加杠杆买入，赚得更多\\n- ✅ **[正确答案]** 选项 3： 不要着急，先查清谁可能更早买入、博主是否收取报酬，以及上涨动力来自哪里\\n\\n\\n---","blueprints":[],"quiz":[{"id":"q-base-12-1","prompt":"博主提供交易所推荐链接，并建议每天进行杠杆期货交易。他如何赚钱？","options":[{"id":"base-12-1-1","label":"只从你的利润中提成，因此与你利益一致","isCorrect":false,"feedback":"不正确。获得交易手续费分成，因此你任何交易都会让他赚钱，即使你亏损"},{"id":"base-12-1-2","label":"获得交易手续费分成，因此你任何交易都会让他赚钱，即使你亏损","isCorrect":true,"feedback":"正确。获得交易手续费分成，因此你任何交易都会让他赚钱，即使你亏损"},{"id":"base-12-1-3","label":"没有任何收入，链接只是给粉丝福利","isCorrect":false,"feedback":"不正确。获得交易手续费分成，因此你任何交易都会让他赚钱，即使你亏损"}],"explanation":"获得交易手续费分成，因此你任何交易都会让他赚钱，即使你亏损","sourceRef":"CAPITAL_BASE:2700–2703 (Verbatim)"},{"id":"q-base-12-2","prompt":"频道展示连续 5 次正确预测，这能说明什么？","options":[{"id":"base-12-2-1","label":"作者肯定是专业人士，可以把钱交给他","isCorrect":false,"feedback":"不正确。单凭这些几乎无法判断；重要的是事件发生前发布的全部预测历史"},{"id":"base-12-2-2","label":"单凭这些几乎无法判断；重要的是事件发生前发布的全部预测历史","isCorrect":true,"feedback":"正确。单凭这些几乎无法判断；重要的是事件发生前发布的全部预测历史"},{"id":"base-12-2-3","label":"第 6 次预测也一定准确","isCorrect":false,"feedback":"不正确。单凭这些几乎无法判断；重要的是事件发生前发布的全部预测历史"}],"explanation":"单凭这些几乎无法判断；重要的是事件发生前发布的全部预测历史","sourceRef":"CAPITAL_BASE:2705–2708 (Verbatim)"},{"id":"q-base-12-3","prompt":"知名博主催促立即购买某个陌生新代币，以免“起飞”。怎样做最安全？","options":[{"id":"base-12-3-1","label":"赶在上涨前全仓买入","isCorrect":false,"feedback":"不正确。不要着急，先查清谁可能更早买入、博主是否收取报酬，以及上涨动力来自哪里"},{"id":"base-12-3-2","label":"加杠杆买入，赚得更多","isCorrect":false,"feedback":"不正确。不要着急，先查清谁可能更早买入、博主是否收取报酬，以及上涨动力来自哪里"},{"id":"base-12-3-3","label":"不要着急，先查清谁可能更早买入、博主是否收取报酬，以及上涨动力来自哪里","isCorrect":true,"feedback":"正确。不要着急，先查清谁可能更早买入、博主是否收取报酬，以及上涨动力来自哪里"}],"explanation":"不要着急，先查清谁可能更早买入、博主是否收取报酬，以及上涨动力来自哪里","sourceRef":"CAPITAL_BASE:2710–2713 (Verbatim)"}],"source":{"file":"00_FREE_GIFT_MakeCash_Crypto_And_Capital_Base_15_Lessons.md","sha256":"88a3efb162434bb8a9b3b000caee579d9c27005a8ea46ddf4ef9cafb50dc45cc","lineStart":2482,"lineEnd":2718}}')}}]);